-- House rules check in the base (BR-LST-005, BR-LST-006, issue #23). The wizard already asks to
-- rephrase "Other house rules" and the host's own items that exclude people; now a listing with them
-- can't be active, paused or filled even when written straight to the API. listings_check_publishable
-- names it as 'house_rules', which publish_listing returns in `missing`.
-- discrimination_check below is generated from core/text-checks.js and
-- tests/unit/risk-parity.test.js fails if they drift.

-- GENERATED by tests/fixtures/risk-sql.js from DISCRIMINATION_PHRASES in core/text-checks.js. Do not edit by hand.
-- BR-LST-005: the same normalized text, inclusive wording and list as discriminationCheck.
create or replace function public.discrimination_check(p_text text)
returns boolean
language sql
stable
set search_path = public, extensions
as $$
  with h as (
    select regexp_replace(regexp_replace(' ' || btrim(regexp_replace(replace(replace(lower(extensions.unaccent(coalesce(p_text, ''))), '’', ''), '''', ''),
      '[^a-z0-9$]+', ' ', 'g')) || ' ', ' all( [a-z0-9]+){1,6} (welcome|welcomed) ', ' ', 'g'), ' [a-z0-9]+ (friendly|welcome|welcomed|welcoming) ', ' ', 'g') as t
  )
  select exists (
    select 1 from h, unnest(array['race', 'racial', 'ethnic', 'ethnicity', 'nationality', 'nationalities', 'cultural background', 'asian', 'asians', 'indian', 'indians', 'chinese', 'african', 'africans', 'aboriginal', 'aboriginals', 'indigenous', 'european', 'europeans', 'caucasian', 'caucasians', 'whites only', 'white only', 'white people', 'blacks', 'black people', 'australians only', 'australian only', 'aussies only', 'aussie only', 'locals only', 'english speakers only', 'foreigner', 'foreigners', 'immigrant', 'immigrants', 'migrant', 'migrants', 'refugee', 'refugees', 'accent', 'religion', 'religious', 'christian', 'christians', 'catholic', 'catholics', 'muslim', 'muslims', 'islam', 'islamic', 'jew', 'jews', 'jewish', 'hindu', 'hindus', 'sikh', 'sikhs', 'buddhist', 'buddhists', 'atheist', 'atheists', 'church goer', 'age limit', 'age range', 'your age', 'aged', 'young people', 'young person', 'older people', 'older person', 'elderly', 'old people', 'retiree', 'retirees', 'pensioner', 'pensioners', 'twenties', 'thirties', 'forties', 'fifties', 'millennial', 'millennials', 'gender', 'male', 'males', 'female', 'females', 'men only', 'women only', 'man only', 'woman only', 'guys only', 'girls only', 'ladies only', 'gents only', 'no men', 'no women', 'no guys', 'no girls', 'no ladies', 'gay', 'gays', 'lesbian', 'lesbians', 'straight only', 'heterosexual', 'homosexual', 'homosexuals', 'bisexual', 'lgbt', 'lgbtq', 'lgbtqi', 'queer', 'transgender', 'sexual orientation', 'sexuality']::text[]) p
    where h.t like '% ' || p || ' %'
  ) or exists (
    select 1 from h, unnest(array[' (under|over|below|above) (?!18s? )\d{2}s? ', ' \d{2} ?(yo|y o|years old|year olds|yrs old) ', ' \d{2} to \d{2} (yo|years|year olds) ']::text[]) r
    where h.t ~ r
  )
$$;

-- Only listings_check_publishable calls it; the web checks with core/text-checks.js.
revoke execute on function public.discrimination_check(text) from public, anon, authenticated;

-- The same function as 20261105090000_listings.sql plus the house rules check.
create or replace function public.listings_check_publishable()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  missing text[] := '{}';
  entering boolean;
  open_count integer;
  owner_limit integer;
begin
  if new.status not in ('active', 'paused', 'filled') then
    return new;
  end if;
  if new.title is null then missing := array_append(missing, 'title'); end if;
  if new.suburb_id is null then missing := array_append(missing, 'suburb_id'); end if;
  if new.public_lat is null or new.public_lng is null then missing := array_append(missing, 'public_circle'); end if;
  if new.place_type is null then missing := array_append(missing, 'place_type'); end if;
  if new.bathroom is null then missing := array_append(missing, 'bathroom'); end if;
  if new.weekly_price is null then missing := array_append(missing, 'weekly_price'); end if;
  if new.bills_included is null then missing := array_append(missing, 'bills_included'); end if;
  if new.bond is null then missing := array_append(missing, 'bond'); end if;
  if new.furnished is null then missing := array_append(missing, 'furnished'); end if;
  if new.accuracy_declared_at is null then missing := array_append(missing, 'accuracy_declared_at'); end if;
  if new.availability_type is null
     or (new.availability_type = 'from_date' and new.available_from is null) then
    missing := array_append(missing, 'availability');
  end if;
  -- BR-LST-005: "Other house rules" pass the risk and the discrimination checks, the host's own
  -- items the discrimination one (BR-LST-006), as the wizard checks with core/text-checks.js.
  if public.risk_check(new.other_rules) or public.discrimination_check(new.other_rules)
     or exists (select 1 from unnest(new.custom_items) i where public.discrimination_check(i)) then
    missing := array_append(missing, 'house_rules');
  end if;

  entering := tg_op = 'INSERT' or old.status not in ('active', 'paused', 'filled')
              or new.availability_type is distinct from old.availability_type;
  if entering and not exists (select 1 from public.listing_private p where p.listing_id = new.id) then
    missing := array_append(missing, 'address');
  end if;
  if entering and (select count(*) from public.listing_photos f where f.listing_id = new.id) < 3 then
    missing := array_append(missing, 'photos');
  end if;
  if entering and not 'availability' = any (missing) and (
       (new.availability_type = 'roster' and not exists (select 1 from public.rosters r where r.user_id = new.owner_id))
       or (new.availability_type = 'ranges' and not exists (select 1 from public.listing_availability_ranges a where a.listing_id = new.id))) then
    missing := array_append(missing, 'availability');
  end if;
  if entering and not exists (select 1 from auth.users u where u.id = new.owner_id and u.phone_confirmed_at is not null and u.email_confirmed_at is not null) then
    missing := array_append(missing, 'verified_contact');
  end if;

  if cardinality(missing) > 0 then
    raise exception 'Listing is not ready to publish: %', array_to_string(missing, ', ') using errcode = '23514';
  end if;

  if new.status in ('active', 'paused') and (tg_op = 'INSERT' or old.status not in ('active', 'paused')) then
    -- BR-LST-007
    select count(*) into open_count from public.listings l
      where l.owner_id = new.owner_id and l.status in ('active', 'paused') and l.id <> new.id;
    select listing_limit into owner_limit from public.profiles where id = new.owner_id;
    if open_count >= coalesce(owner_limit, 5) then
      raise exception 'Listing limit reached' using errcode = '23514';
    end if;
  end if;
  return new;
end;
$$;
